content.css:
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.strategic-sunburst-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: var(--ss-font, 11px);
}
.strategic-sunburst-root svg {
  shape-rendering: geometricPrecision;
}
/* ── Landing page ── */
.ss-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--bf-muted, #667079);
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
.ss-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--bf-muted, #667079);
  font-size: 12px;
  text-align: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
  letter-spacing: 0.2px;
}
/* ── Layout: toolbar · ask · body (chart | top items | rail | panel) ── */
.ss-content {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  box-sizing: border-box;
  padding-bottom: 24px;
  /* licence badge clear-zone */
}
.ss-body {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
}
.ss-chart-col {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
}
.ss-chart-col svg {
  display: block;
}
/* ── Toolbar ── */
.ss-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px 12px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  font-size: var(--ss-tb-font, 11px);
  color: var(--bf-text, #242424);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.ss-toolbar__right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.ss-howto {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  flex: 1 1 260px;
  color: var(--bf-muted, #667079);
  line-height: 1.35;
}
.ss-howto__label {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: calc(var(--ss-tb-font, 11px) - 1.5px);
  color: var(--ss-insight-accent, #E8612A);
  white-space: nowrap;
}
.ss-howto__text {
  min-width: 0;
}
.ss-howto__x {
  border: 0;
  background: transparent;
  color: var(--bf-muted, #667079);
  cursor: pointer;
  font: inherit;
  padding: 0 2px;
}
.ss-howto__x:hover {
  color: var(--bf-text, #242424);
}
/* Info button: suite chrome, fixed (see BFusion-Apps/CLAUDE.md). */
.ss-info {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E3E6EC;
  background: #FFFFFF;
  color: #6B7280;
  font-family: inherit;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  line-height: 1;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.12s ease;
}
.ss-info:hover {
  background: #E8612A;
  color: #FFFFFF;
  transform: scale(1.05);
}
.ss-info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.ss-info-pop {
  position: absolute;
  top: 34px;
  right: 10px;
  z-index: 30;
  width: 340px;
  max-width: calc(100% - 20px);
  max-height: 70%;
  overflow-y: auto;
  padding: 10px 12px;
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #242424);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  box-shadow: 0 6px 20px var(--bf-shadow, rgba(15, 23, 42, 0.12));
  font-size: 11px;
  line-height: 1.45;
}
.ss-info-pop__title {
  font-weight: 700;
  font-size: 12px;
  padding-bottom: 5px;
  margin-bottom: 6px;
  border-bottom: 2px solid var(--ss-insight-accent, #E8612A);
}
.ss-info-pop__list {
  margin: 0;
  padding-left: 16px;
}
.ss-info-pop__list li {
  margin-bottom: 4px;
}
/* ── Ask: question chips (same as KPI Grid) ── */
.ss-ask {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 5px 12px 6px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  flex-shrink: 0;
  font-size: var(--ss-tb-font, 11px);
}
.ss-ask__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.ss-ask__label {
  font-size: calc(var(--ss-tb-font, 11px) - 0.5px);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ss-insight-accent, #E8612A);
  margin-right: 2px;
}
.ss-ask__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 5px 3px 11px;
  border-radius: 999px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  font: inherit;
  cursor: pointer;
  transition: border-color 0.12s ease, background 0.12s ease;
}
.ss-ask__chip:hover {
  border-color: var(--ss-insight-accent, #E8612A);
}
.ss-ask__chip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.ss-ask__chip--active {
  background: rgba(232, 97, 42, 0.12);
  border-color: var(--ss-insight-accent, #E8612A);
  color: var(--bf-strong, #1F2A44);
  font-weight: 600;
}
.ss-ask__count {
  min-width: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  font-size: calc(var(--ss-tb-font, 11px) - 1px);
  font-weight: 700;
  line-height: 16px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.ss-ask__count--none {
  color: #16a34a;
}
.ss-ask__chip--active .ss-ask__count {
  background: var(--ss-insight-accent, #E8612A);
  border-color: var(--ss-insight-accent, #E8612A);
  color: #FFFFFF;
}
.ss-ask__answer {
  display: flex;
  align-items: baseline;
  gap: 8px;
  color: var(--bf-strong, #1F2A44);
  font-size: calc(var(--ss-tb-font, 11px) + 1px);
}
.ss-ask__arrow {
  color: var(--ss-insight-accent, #E8612A);
  font-weight: 700;
}
.ss-ask__text {
  flex: 1;
  font-weight: 600;
}
.ss-ask__clear {
  border: 0;
  background: transparent;
  color: var(--bf-muted, #667079);
  cursor: pointer;
  font: inherit;
  padding: 0 4px;
}
.ss-ask__clear:hover {
  color: var(--bf-text, #242424);
}
/* ── Insight rail: suite chrome, fixed (see BFusion-Apps/CLAUDE.md) ── */
.bfusion-insight-strip {
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
  flex: 0 0 26px;
  width: 26px;
}
.bfusion-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.bfusion-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-size: 9px;
  font-weight: 650;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
}
.bfusion-insight-strip:hover,
.bfusion-insight-strip:focus {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
.bfusion-insight-strip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
/* ── Insight panel ── */
.ss-panel {
  flex: 0 0 260px;
  width: 260px;
  max-width: 320px;
  box-sizing: border-box;
  padding: 8px 10px;
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  background: linear-gradient(180deg, var(--bf-tile, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%);
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  font-size: var(--ss-insight-font, 11px);
  color: var(--bf-text, #242424);
}
.ss-panel [data-tone="good"] {
  --tone: #16a34a;
}
.ss-panel [data-tone="warn"] {
  --tone: #d97706;
}
.ss-panel [data-tone="bad"] {
  --tone: #dc2626;
}
.ss-panel [data-tone="info"] {
  --tone: #1e40af;
}
.bfusion-scope-chip {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 2px 8px;
  margin: 0 4px 6px 0;
  border: 1px solid rgba(217, 123, 41, 0.35);
  border-radius: 999px;
  background: rgba(217, 123, 41, 0.08);
  color: #9a5418;
  font-family: inherit;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bfusion-scope-chip:hover {
  background: rgba(217, 123, 41, 0.16);
}
.bfusion-scope-chip__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-scope-chip__x {
  color: #b1712f;
  font-weight: 700;
}
.ss-panel__header {
  padding-bottom: 6px;
  margin-bottom: 8px;
  border-bottom: 2px solid var(--ss-insight-accent, #E8612A);
}
.ss-panel__title {
  font-size: var(--ss-insight-header-font, 13px);
  font-weight: 700;
  color: var(--bf-text, #242424);
}
.ss-panel__sub {
  font-size: calc(var(--ss-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  margin-top: 1px;
}
.ss-verdict {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  margin-bottom: 8px;
  border-radius: 6px;
  background-color: color-mix(in srgb, var(--tone) 8%, var(--bf-tile, #FFFFFF));
  border: 1px solid color-mix(in srgb, var(--tone) 30%, var(--bf-tile, #FFFFFF));
  border-left: 4px solid var(--tone);
}
.ss-verdict__badge {
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background-color: var(--tone);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 700;
}
.ss-verdict__text {
  min-width: 0;
}
.ss-verdict__title {
  font-size: calc(var(--ss-insight-font, 11px) + 1px);
  font-weight: 700;
  line-height: 1.3;
  color: color-mix(in srgb, var(--tone) 70%, var(--bf-text, #242424));
}
.ss-verdict__sub {
  font-size: calc(var(--ss-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  margin-top: 2px;
  line-height: 1.35;
}
.ss-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 8px;
}
.ss-tile {
  padding: 5px 8px;
  border-radius: 4px;
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 3px solid var(--tone);
}
.ss-tile__val {
  font-size: calc(var(--ss-insight-font, 11px) + 3px);
  font-weight: 700;
  color: var(--bf-text, #242424);
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.ss-tile__lbl {
  font-size: calc(var(--ss-insight-font, 11px) - 2px);
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-top: 1px;
}
.ss-health {
  margin-bottom: 8px;
}
.ss-health__bar {
  display: flex;
  height: 10px;
  border-radius: 5px;
  overflow: hidden;
  background: var(--bf-rule, #E5E7EB);
}
.ss-health__seg {
  height: 100%;
}
.ss-health__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  margin-top: 4px;
  font-size: calc(var(--ss-insight-font, 11px) - 1.5px);
  color: var(--bf-muted, #667079);
}
.ss-health__legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.ss-health__dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.ss-panel__section {
  margin: 10px 0 6px;
  font-size: calc(var(--ss-insight-font, 11px) - 1px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ss-insight-accent, #E8612A);
}
.ss-card {
  border-radius: 6px;
  padding: 8px;
  margin-bottom: 8px;
  background-color: color-mix(in srgb, var(--tone) 6%, var(--bf-tile, #FFFFFF));
  border: 1px solid color-mix(in srgb, var(--tone) 28%, var(--bf-tile, #FFFFFF));
}
.ss-card[data-tone="info"] {
  background-color: var(--bf-tile, #FFFFFF);
  border-color: var(--bf-rule, #E5E7EB);
}
.ss-card--active {
  box-shadow: 0 0 0 2px #D97B29;
}
.ss-card__head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
}
.ss-card__icon {
  font-size: 12px;
  line-height: 1;
  color: var(--tone);
}
.ss-card__title {
  font-size: calc(var(--ss-insight-font, 11px) - 1px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: color-mix(in srgb, var(--tone) 70%, var(--bf-text, #242424));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ss-card__headline {
  font-size: calc(var(--ss-insight-font, 11px) + 0.5px);
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 3px;
}
.ss-card__item {
  font-size: calc(var(--ss-insight-font, 11px) - 0.5px);
  line-height: 1.45;
  padding: 1px 0;
  color: var(--bf-text, #242424);
}
.ss-card__item--muted {
  color: var(--bf-muted, #667079);
  font-style: italic;
}
.ss-card__action {
  font-weight: 600;
}
.ss-card__filter {
  appearance: none;
  margin-top: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--tone) 40%, var(--bf-tile, #FFFFFF));
  background: var(--bf-tile, #FFFFFF);
  color: color-mix(in srgb, var(--tone) 75%, var(--bf-text, #242424));
  font-family: inherit;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
}
.ss-card__filter:hover,
.ss-card__filter[aria-pressed="true"] {
  background: color-mix(in srgb, var(--tone) 12%, var(--bf-tile, #FFFFFF));
}
.ss-card__filter:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* ── Responsive ── */
.strategic-sunburst-root.wl-medium .ss-panel {
  flex-basis: 220px;
  width: 220px;
}
.strategic-sunburst-root.wl-narrow .ss-panel {
  position: absolute;
  top: 0;
  right: 26px;
  bottom: 0;
  z-index: 20;
  width: 260px;
  max-width: calc(100% - 40px);
  box-shadow: -4px 0 16px var(--bf-shadow, rgba(15, 23, 42, 0.12));
}
.strategic-sunburst-root.wl-narrow .ss-ask__row {
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: thin;
}
.strategic-sunburst-root.wl-narrow .ss-ask__chip {
  flex-shrink: 0;
}
.strategic-sunburst-root.wl-narrow .ss-howto {
  display: none !important;
}
/* ══ Sunburst ══════════════════════════════════════════════════════════ */
/* ── Chart column: legend over the ring ── */
.ss-chart-col {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.ss-chart-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
}
.ss-chart-wrap svg {
  display: block;
}
/* ── Arcs ── */
.ss-arc {
  cursor: pointer;
  stroke-width: 1;
  transition: opacity 0.2s ease;
}
/* Pull-out of the selected wedge: animated on a selection change only, not on first paint. */
.ss-chart--animate .ss-arc,
.ss-chart--animate .ss-label-g {
  transition: opacity 0.2s ease, transform 0.22s ease-out;
}
.ss-arc:hover {
  filter: brightness(1.1);
  stroke-width: 1.5;
}
.ss-arc.dimmed {
  opacity: 0.22;
}
.ss-arc--selected {
  stroke: var(--bf-strong, #1F2A44) !important;
  stroke-width: 2 !important;
  filter: drop-shadow(0 2px 4px var(--bf-shadow, rgba(15, 23, 42, 0.12)));
}
.ss-arc--scoped {
  stroke: #E8612A !important;
  stroke-width: 2 !important;
}
.ss-arc--preview {
  stroke: #E8612A !important;
  stroke-width: 2.5 !important;
  filter: brightness(1.08);
}
/* ── Labels ── */
.ss-label {
  font-size: 10px;
  font-weight: 600;
  pointer-events: none;
  text-anchor: middle;
  transition: opacity 0.2s ease;
}
.ss-label-g.dimmed {
  opacity: 0.3;
}
/* ── Centre ── */
.ss-center-text {
  text-anchor: middle;
  fill: var(--bf-text, #242424);
  pointer-events: none;
}
.ss-center-name {
  font-size: 14px;
  font-weight: 700;
}
.ss-center-value {
  font-size: 12px;
  fill: var(--bf-muted, #667079);
  font-variant-numeric: tabular-nums;
}
/* ── Legend ── */
.ss-legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  padding: 6px 12px 0;
  font-size: calc(var(--ss-font, 11px) - 0.5px);
  color: var(--bf-muted, #667079);
  flex-shrink: 0;
}
.ss-legend__title {
  font-weight: 700;
  color: var(--bf-text, #242424);
  margin-right: 2px;
}
.ss-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}
.ss-legend__btn {
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: var(--bf-text, #242424);
  font: inherit;
  padding: 1px 7px 1px 4px;
  cursor: pointer;
}
.ss-legend__btn:hover {
  border-color: var(--bf-rule, #E5E7EB);
  background: var(--bf-surface-alt, #F4F5F7);
}
.ss-legend__btn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.ss-legend__btn--on {
  border-color: var(--ss-insight-accent, #E8612A);
  background: rgba(232, 97, 42, 0.1);
  font-weight: 600;
}
.ss-legend__swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 2px;
  flex-shrink: 0;
}
.ss-legend__ramp {
  display: inline-block;
  width: 110px;
  height: 8px;
  border-radius: 4px;
}
.ss-legend__tick {
  font-variant-numeric: tabular-nums;
}
.ss-legend__more {
  font-style: italic;
}
.ss-legend__warn {
  color: #b45309;
  font-weight: 600;
}
/* ── Breadcrumb (only while something is selected) ── */
.ss-crumbs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  min-width: 0;
  flex: 1 1 260px;
}
.ss-crumbs__item {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 999px;
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  font: inherit;
  padding: 1px 9px;
  cursor: pointer;
  white-space: nowrap;
}
.ss-crumbs__item:hover {
  border-color: var(--ss-insight-accent, #E8612A);
}
.ss-crumbs__item:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.ss-crumbs__item--current {
  cursor: default;
  border-color: var(--ss-insight-accent, #E8612A);
  background: rgba(232, 97, 42, 0.1);
  font-weight: 600;
}
.ss-crumbs__val {
  color: var(--bf-muted, #667079);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}
.ss-crumbs__sep {
  color: var(--bf-muted, #667079);
}
.ss-info-pop__body {
  margin-bottom: 6px;
  color: var(--bf-muted, #667079);
}
/* ── Panel: alignment bands, clickable breakdown ── */
.ss-panel__minor {
  font-size: calc(var(--ss-insight-font, 11px) - 1.5px);
  color: var(--bf-muted, #667079);
  margin-bottom: 3px;
}
.ss-health__seg--strong {
  background: #16a34a;
}
.ss-health__seg--moderate {
  background: #f59e0b;
}
.ss-health__seg--weak {
  background: #dc2626;
}
.ss-health__seg--none {
  background: #B8BEC7;
}
.ss-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.ss-list__row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 4px;
  margin: 0 -4px;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.12s ease;
}
.ss-list__row:hover {
  background: rgba(232, 97, 42, 0.07);
}
.ss-list__row:hover .ss-list__name {
  color: var(--ss-insight-accent, #E8612A);
}
.ss-list__row:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.ss-list__row--on {
  background: rgba(232, 97, 42, 0.12);
  box-shadow: inset 3px 0 0 var(--ss-insight-accent, #E8612A);
}
.ss-list__top {
  display: flex;
  align-items: center;
  gap: 6px;
}
.ss-list__dot {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  flex-shrink: 0;
}
.ss-list__name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ss-list__pct {
  color: var(--bf-muted, #667079);
  font-variant-numeric: tabular-nums;
}
.ss-list__val {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  min-width: 40px;
  text-align: right;
}
.ss-list__track {
  display: block;
  height: 4px;
  border-radius: 2px;
  background: var(--bf-rule, #E5E7EB);
  overflow: hidden;
  margin-left: 14px;
}
.ss-list__fill {
  display: block;
  height: 100%;
  border-radius: 2px;
}
/* ── Top items column ── */
.ss-secondary-wrap {
  display: flex;
  flex-direction: column;
  flex: 0 0 170px;
  width: 170px;
  box-sizing: border-box;
  padding: 8px 10px;
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface, #F8F9FB);
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
}
.ss-secondary-title {
  font-weight: 700;
  font-size: 12px;
  color: var(--bf-text, #242424);
  padding-bottom: 4px;
  border-bottom: 2px solid var(--ss-insight-accent, #E8612A);
}
.ss-secondary-subtitle {
  font-size: 10px;
  color: var(--bf-muted, #667079);
  margin: 2px 0 8px;
}
.ss-secondary-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ss-secondary-item {
  cursor: pointer;
  padding: 3px 4px;
  border-radius: 3px;
  transition: background 0.12s ease;
}
.ss-secondary-item:hover {
  background: rgba(232, 97, 42, 0.07);
}
.ss-secondary-item:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.ss-secondary-item--on {
  background: rgba(232, 97, 42, 0.12);
  box-shadow: inset 3px 0 0 var(--ss-insight-accent, #E8612A);
}
.ss-secondary-name-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px;
  font-size: 10px;
  margin-bottom: 2px;
}
.ss-secondary-name {
  color: var(--bf-text, #242424);
  font-weight: 500;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ss-secondary-value {
  color: var(--bf-muted, #667079);
  font-weight: 600;
  font-size: 9.5px;
  font-variant-numeric: tabular-nums;
}
.ss-secondary-track {
  height: 6px;
  background: var(--bf-surface-alt, #F4F5F7);
  border-radius: 3px;
  overflow: hidden;
}
.ss-secondary-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.25s ease;
}
.strategic-sunburst-root.wl-medium .ss-secondary-wrap {
  flex-basis: 140px;
  width: 140px;
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
